SELECT ?s ?label WHERE {
  ?s rdfs:label ?label .
  FILTER(?label LIKE "%DataCenter%")
}
LIMIT 50

SELECT ?s ?label WHERE {
  ?s rdfs:label ?label .
  FILTER(?label LIKE "%ZN_6%")
}
LIMIT 50

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?p ?t ?tsid WHERE {
  ?z rdfs:label "DataCenter_top_ZN_6" .
  ?z a brick:Zone .
  ?z brick:hasPoint ?p .
  ?p a ?t .
  OPTIONAL { ?p brick:ref#hasExternalReference ?ext ; ?ext brick:ref#hasTimeseriesId ?tsid }
}
LIMIT 200

PREFIX b: <https://brickschema.org/schema/Brick#>
